assertion.value:
const metadata = context.providerResponse?.metadata;
const calls = metadata?.tool_calls;
if (!Array.isArray(calls)) {
  return { pass: false, score: 0, reason: "Falta el registro de herramientas." };
}
const validation = calls.find(
  (call) =>
    call.name === "check_weather_tool" &&
    call.arguments?.target_date === "2000-01-01" &&
    call.status === "returned" &&
    /fecha pasada/i.test(String(call.result))
);
const bookingAttempt = calls.some(
  (call) => call.name === "create_appointment_tool"
);
const noAppointments =
  Array.isArray(metadata.appointments) &&
  metadata.appointments.length === 0;
const pass = Boolean(validation) && !bookingAttempt && noAppointments;
return {
  pass,
  score: pass ? 1 : 0,
  reason: pass
    ? "La herramienta rechazó la fecha correcta, sin intentar crear ni guardar una cita."
    : "Se esperaba validar 2000-01-01 con check_weather_tool y no intentar crear ni guardar una cita."
};

